// On pose la meme question N fois, avec une temperature > 0
async function autoCoherence(question, N) {
  const reponses = []
  for (let i = 0; i < N; i++) {
    const r = await modele(question, { temperature: 0.7 })
    reponses.push(r.reponseFinale) // ex : "42"
  }

  // Vote majoritaire : on compte les occurrences de chaque reponse
  const comptes = {}
  for (const r of reponses) {
    comptes[r] = (comptes[r] || 0) + 1
  }

  // On garde la reponse qui revient le plus souvent
  let gagnante = null, max = 0
  for (const [valeur, n] of Object.entries(comptes)) {
    if (n > max) { max = n; gagnante = valeur }
  }
  return gagnante
}

// Ex : 5 reponses = [42, 42, 37, 42, 40] -> on garde 42 (majoritaire)
